for m, j in fj.items():
    st = c.status(j)["status"]
    if st == "queued":
        print("cancel", m, c.cancel(j))
    else:
        print(m, st, "(leave)")
# submit v3
v3 = {}
for m in ["development-01","development-06","development-08","development-12"]:
    job = c.submit("/workspace/submission", model=m, pilot=False)
    v3[m] = job["id"]
    print(m, job["id"], job.get("status"), flush=True)
json.dump(v3, open("/workspace/build/v3_jobs.json","w"))
EOF",
